# Expected values are SymPy's outputs for the same calls (holonomic), with ** written ^.

skip_on_cran()

x <- Symbol("x")
RR <- DifferentialOperators(holonomic_ring(x), "Dx"); Dx <- RR$Dx
fmt <- function(r) {
  if (inherits(r, c("HolonomicFunction", "DifferentialOperator", "HolonomicSequence"))) return(format(r))
  if (is.list(r) && !is_sym(r)) return(paste0(if (length(r) == 3L || length(r) == 2L && !inherits(r[[1L]], "list")) "(" else "[", paste(vapply(r, fmt, ""), collapse = ", "), if (length(r) == 3L || length(r) == 2L && !inherits(r[[1L]], "list")) ")" else "]"))
  if (is.numeric(r)) return(format(r))
  sstr(r)
}

test_that("holonomic functions match SymPy", {
  expect_equal(fmt(x * Dx + x^2 * Dx^2), "(x)*Dx + (x^2)*Dx^2")
  expect_equal(fmt((x^2 + 1) + Dx + x * Dx^5), "(x^2 + 1) + (1)*Dx + (x)*Dx^5")
  expect_equal(fmt((x * Dx + x^2 + 1 - Dx * (x^3 + x))^3), "(-48*x^6) + (-57*x^7)*Dx + (-15*x^8)*Dx^2 + (-x^9)*Dx^3")
  expect_equal(fmt((x * Dx^2 + (x^2 + 3) * Dx^5) * (Dx + x^2)), "(2*x) + (4*x^2)*Dx + (x^3)*Dx^2 + (20*x^2 + x + 60)*Dx^3 + (10*x^3 + 30*x)*Dx^4 + (x^4 + 3*x^2)*Dx^5 + (x^2 + 3)*Dx^6")
  expect_equal(fmt(HolonomicFunction(Dx^2 * x, x)), "HolonomicFunction((2)*Dx + (x)*Dx^2, x)")
  expect_equal(fmt(HolonomicFunction(x * Dx + 1, x) + HolonomicFunction(Dx + 1, x)), "HolonomicFunction((x - 2) + (x^2 - 2)*Dx + (x^2 - x)*Dx^2, x)")
  expect_equal(fmt(HolonomicFunction(x * Dx + Dx^2 * (x^2 + 2), x) + HolonomicFunction(Dx - 3, x)), "HolonomicFunction((-6*x^2 - 14*x - 50/3) + (-15*x^3 - 28*x^2 - 30*x + 140/9)*Dx + (-3*x^4 - 8*x^2/3 + 14*x/9 - 50/3)*Dx^2 + (x^4 + 5*x^3/3 + 38*x^2/9 + 10*x/3 + 40/9)*Dx^3, x)")
  expect_equal(fmt(HolonomicFunction(Dx^5 - 1, x) + HolonomicFunction(x^3 + Dx, x)), "HolonomicFunction((-x^18 + 45*x^14 - 525*x^10 + 1575*x^6 - x^3 - 630*x^2) + (-x^15 + 30*x^11 - 195*x^7 + 210*x^3 - 1)*Dx + (x^18 - 45*x^14 + 525*x^10 - 1575*x^6 + x^3 + 630*x^2)*Dx^5 + (x^15 - 30*x^11 + 195*x^7 - 210*x^3 + 1)*Dx^6, x)")
  expect_equal(fmt(HolonomicFunction((x^2 + 3*x + 8)*Dx - (2*x + 3), x) + HolonomicFunction((x^3 - 7*x + 5)*Dx - (3*x^2 - 7), x)), "HolonomicFunction((6*x^2 + 18*x + 14) + (-4*x^3 - 18*x^2 - 62*x + 10)*Dx + (x^4 + 6*x^3 + 31*x^2 - 10*x - 71)*Dx^2, x)")
  expect_equal(fmt(HolonomicFunction(Dx+x+x*Dx^2, x) * HolonomicFunction(x*Dx+Dx*x+Dx^2, x)), "HolonomicFunction((4*x^6 + 2*x^4 + 3*x^2 + 3/2) + (12*x^5 - 2*x^3 + 12*x)*Dx + (4*x^6 + 10*x^4 + 6*x^2 + 1)*Dx^2 + (4*x^5 + 2*x^3 + 2*x)*Dx^3 + (x^4 + x^2/2)*Dx^4, x)")
  expect_equal(fmt(HolonomicFunction(Dx^2+1, x) * HolonomicFunction(Dx-1, x)), "HolonomicFunction((2) + (-2)*Dx + (1)*Dx^2, x)")
  expect_equal(fmt(HolonomicFunction(Dx^2+1+x+Dx, x) * HolonomicFunction((Dx*x-1)^2, x)), "HolonomicFunction((x^7 + 11*x^6/4 + 4*x^5 + x^4 - 3*x^3/2 - 7*x^2/4 - 2*x - 1/2) + (2*x^6 + 13*x^5/2 + 6*x^4 - 3*x^3/4 - 11*x^2/4 - 3*x/2 - 1/2)*Dx + (2*x^6 + 9*x^5/2 + 15*x^4/4 - 3*x^3/4 - 3*x^2/2 - 3*x/2 - 1/2)*Dx^2 + (2*x^5 + 5*x^4/2 + 3*x^3/2 - x^2/2 - x)*Dx^3 + (x^5 + 3*x^4/4 - x^2/4)*Dx^4, x)")
  expect_equal(fmt(HolonomicFunction(x*Dx^2-1, x) * HolonomicFunction(Dx*x-x, x)), "HolonomicFunction((x - 3) + (2 - 2*x)*Dx + (x)*Dx^2, x)")
  expect_equal(fmt(HolonomicFunction(Dx+x+x*Dx^2, x)^3), "HolonomicFunction((9*x^3 + 12*x) + (30*x^2 + 1)*Dx + (10*x^3 + 7*x)*Dx^2 + (6*x^2)*Dx^3 + (x^3)*Dx^4, x)")
  expect_equal(fmt(HolonomicFunction(Dx-1, x, 0, list(3)) + HolonomicFunction(Dx^2+1, x, 0, list(1, 0))), "HolonomicFunction((-1) + (1)*Dx + (-1)*Dx^2 + (1)*Dx^3, x, 0, [4, 3, 2])")
  expect_equal(fmt(HolonomicFunction(Dx - x + Dx^2, x, 0, list(1, 2)) + HolonomicFunction(Dx^2 + x, x, 0, list(1, 0))), "HolonomicFunction((-x^4 - x^3/4 - x^2 + 1/4) + (x^3 + x^2/4 + 3*x/4 + 1)*Dx + (7/4 - 3*x/2)*Dx^2 + (x^2 - 7*x/4 + 1/4)*Dx^3 + (x^2 + x/4 + 1/2)*Dx^4, x, 0, [2, 2, -2, 2])")
  expect_equal(fmt(HolonomicFunction(Dx^2 + 4*x*Dx + x^2, x, 0, list(3, 4)) + HolonomicFunction(Dx^2 + 1, x, 0, list(1, 1))), "HolonomicFunction((x^6 + 2*x^4 - 5*x^2 - 6) + (4*x^5 + 36*x^3 - 32*x)*Dx + (x^6 + 3*x^4 + 5*x^2 - 9)*Dx^2 + (4*x^5 + 36*x^3 - 32*x)*Dx^3 + (x^4 + 10*x^2 - 3)*Dx^4, x, 0, [4, 5, -1, -17])")
  expect_equal(fmt(HolonomicFunction(Dx - 1, x, 2, list(1)) + HolonomicFunction(Dx^3 + x, x, 2, list(3, 0, 1))), "HolonomicFunction((-x^2 - x + 1) + (x^2 + x)*Dx + (-x - 2)*Dx^3 + (x + 1)*Dx^4, x, 2, [4, 1, 2, -5])")
  expect_equal(fmt(HolonomicFunction(Dx^2 + x*Dx - 1, x, 0, list(3, 1)) * HolonomicFunction(Dx^2 + 1, x, 0, list(1, 1))), "HolonomicFunction((x^4 + 14*x^2 + 60) + (4*x)*Dx + (x^4 + 9*x^2 + 20)*Dx^2 + (2*x^3 + 18*x)*Dx^3 + (x^2 + 10)*Dx^4, x, 0, [3, 4, 2, 3])")
  expect_equal(fmt(HolonomicFunction(Dx - 1, x, 0, list(2)) * HolonomicFunction(Dx^2 + 1, x, 0, list(0, 1))), "HolonomicFunction((2) + (-2)*Dx + (1)*Dx^2, x, 0, [0, 2])")
  expect_equal(fmt(HolonomicFunction(Dx - 1, x, 0, list(2)) * HolonomicFunction(x*Dx^2 + 1 + 2*Dx, x, 0, list(0, 1))), "HolonomicFunction((x - 1) + (2 - 2*x)*Dx + (x)*Dx^2, x, 0, [0, 2])")
  expect_equal(fmt(HolonomicFunction(Dx^2 - 1, x, 0, list(1, 3)) * HolonomicFunction(Dx^3 + 1, x, 0, list(1, 2, 1))), "HolonomicFunction((6)*Dx + (3)*Dx^2 + (2)*Dx^3 + (-3)*Dx^4 + (1)*Dx^6, x, 0, [1, 5, 14, 17, 17, 2])")
  expect_equal(fmt(composition(HolonomicFunction(Dx-1, x), x^2+x)), "HolonomicFunction((-2*x - 1) + (1)*Dx, x)")
  expect_equal(fmt(composition(HolonomicFunction(Dx^2+1, x), x^5+x^2+1)), "HolonomicFunction((25*x^12 + 30*x^9 + 12*x^6 + 8*x^3/5) + (-4*x^3 - 2/5)*Dx + (x^4 + 2*x/5)*Dx^2, x)")
  expect_equal(fmt(composition(HolonomicFunction(Dx^2*x+x, x), 2*x^3+x^2+1)), "HolonomicFunction((36*x^9 + 54*x^8 + 30*x^7 + 76*x^6/3 + 56*x^5/3 + 6*x^4 + 2*x^3/3) + (4*x^4 + 8*x^3/3 + x^2/2 - x - 1/6)*Dx + (x^5 + 5*x^4/6 + x^3/6 + x^2/2 + x/6)*Dx^2, x)")
  expect_equal(fmt(composition(HolonomicFunction(Dx^2+1, x), 1-x^2)), "HolonomicFunction((4*x^3) + (-1)*Dx + (x)*Dx^2, x)")
  expect_equal(fmt(composition(HolonomicFunction(Dx^2+1, x), x - 2/(x^2 + 1))), "HolonomicFunction((x^12 + 6*x^10 + 12*x^9 + 15*x^8 + 48*x^7 + 68*x^6 + 72*x^5 + 111*x^4 + 112*x^3 + 54*x^2 + 12*x + 1) + (12*x^8 + 32*x^6 + 24*x^4 - 4)*Dx + (x^12 + 6*x^10 + 4*x^9 + 15*x^8 + 16*x^7 + 20*x^6 + 24*x^5 + 15*x^4 + 16*x^3 + 6*x^2 + 4*x + 1)*Dx^2, x)")
  expect_equal(fmt(to_sequence(HolonomicFunction(Dx - 1, x, 0, list(1)))), "[(HolonomicSequence((-1) + (n + 1)Sn, n), u(0) = 1, 0)]")
  expect_equal(fmt(to_sequence(HolonomicFunction(Dx^2 + 1, x, 0, list(0, 1)))), "[(HolonomicSequence((1) + (n^2 + 3*n + 2)Sn^2, n), u(0) = 0, u(1) = 1, 0)]")
  expect_equal(fmt(to_sequence(HolonomicFunction(Dx^2 + 1 + x^3*Dx, x, 0, list(2, 3)))), "[(HolonomicSequence((n) + (1)Sn^2 + (n^2 + 7*n + 12)Sn^4, n), u(0) = 2, u(1) = 3, u(2) = -1, u(3) = -1/2, u(4) = 1/12, 1)]")
  expect_equal(fmt(series_holonomic(HolonomicFunction(Dx^2 + 2*x*Dx, x, 0, list(0, 1)), n = 10)), "x - x^3/3 + x^5/10 - x^7/42 + x^9/216 + O(x^10)")
  expect_equal(fmt(series_holonomic(composition(HolonomicFunction(Dx - 1, x), x^2, 0, list(1)) * HolonomicFunction(Dx^2 + 1, x, 0, list(1, 0)), n = 10)), "1 + x^2/2 + x^4/24 - 31*x^6/720 - 179*x^8/8064 + O(x^10)")
  expect_equal(fmt(series_holonomic(HolonomicFunction((6+6*x-3*x^2) - (10*x-3*x^2-3*x^3)*Dx + (4-6*x^3+2*x^4)*Dx^2, x, 0, list(0, 1)), n = 7)), "x + x^3/6 - 3*x^4/16 + x^5/20 - 23*x^6/960 + O(x^7)")
  expect_equal(fmt(series_holonomic(HolonomicFunction((6+6*x-3*x^2) - (10*x-3*x^2-3*x^3)*Dx + (4-6*x^3+2*x^4)*Dx^2, x, 0, list(1, 0)), n = 7)), "1 - 3*x^2/4 - x^3/4 - 5*x^4/32 - 3*x^5/40 - 17*x^6/384 + O(x^7)")
  expect_equal(fmt(expr_to_holonomic(sin(x))), "HolonomicFunction((1) + (1)*Dx^2, x, 0, [0, 1])")
  expect_equal(fmt(expr_to_holonomic(cos(x))), "HolonomicFunction((1) + (1)*Dx^2, x, 0, [1, 0])")
  expect_equal(fmt(expr_to_holonomic(exp(x))), "HolonomicFunction((-1) + (1)*Dx, x, 0, [1])")
  expect_equal(fmt(expr_to_holonomic(x^2 + 3*x + 1)), "HolonomicFunction((-2*x - 3) + (x^2 + 3*x + 1)*Dx, x, 0, [1])")
  expect_equal(fmt(expr_to_holonomic(1/(x + 1))), "HolonomicFunction((1) + (x + 1)*Dx, x, 0, [1])")
  expect_equal(fmt(expr_to_holonomic(1/x, x0 = 1)), "HolonomicFunction((1) + (x)*Dx, x, 1, [1])")
  expect_equal(fmt(expr_to_holonomic(sin(x)^2)), "HolonomicFunction((4)*Dx + (1)*Dx^3, x, 0, [0, 0, 2])")
  expect_equal(fmt(expr_to_holonomic(exp(x)*sin(x))), "HolonomicFunction((2) + (-2)*Dx + (1)*Dx^2, x, 0, [0, 1])")
  expect_equal(fmt(expr_to_holonomic(sin(x) + cos(x))), "HolonomicFunction((1) + (1)*Dx^2, x, 0, [1, 1])")
  expect_equal(fmt(expr_to_holonomic(sin(x)*x^2)), "HolonomicFunction((x^2 + 6) + (-4*x)*Dx + (x^2)*Dx^2, x, 0, [0, 0])")
  expect_equal(fmt(expr_to_holonomic(exp(x^2))), "HolonomicFunction((-2*x) + (1)*Dx, x, 0, [1])")
  expect_equal(fmt(expr_to_holonomic(sin(x)) + expr_to_holonomic(1/x, x0 = 1)), "HolonomicFunction((x^2 + 6) + (x^3 + 2*x)*Dx + (x^2 + 6)*Dx^2 + (x^3 + 2*x)*Dx^3, x, 1, [sin(1) + 1, -1 + cos(1), 2 - sin(1)])")
  expect_equal(fmt(expr_to_holonomic(sin(x)) * expr_to_holonomic(1/x, x0 = 1)), "HolonomicFunction((x) + (2)*Dx + (x)*Dx^2, x, 1, [sin(1), -sin(1) + cos(1)])")
  expect_equal(fmt(to_hyper(expr_to_holonomic(sin(x)))), "x*hyper((), (3/2,), -x^2/4)")
  expect_equal(fmt(to_hyper(expr_to_holonomic(exp(x)))), "hyper((), (), x)")
  expect_equal(fmt(to_expr_holonomic(expr_to_holonomic(cos(x)))), "cos(x)")
  expect_equal(fmt(integrate_holonomic(HolonomicFunction(Dx^2 + 1, x, 0, list(0, 1)), x)), "HolonomicFunction((1)*Dx + (1)*Dx^3, x, 0, [0, 0, 1])")
  expect_equal(fmt(integrate_holonomic(HolonomicFunction(Dx^2 + 1, x, 0, list(0, 1)), list(x, 0, x))), "HolonomicFunction((1)*Dx + (1)*Dx^3, x, 0, [0, 0, 1])")
  expect_equal(fmt(integrate_holonomic(HolonomicFunction(Dx^2 + 1, x, 0, list(0, 1)), list(x, 0, 1))), "1 - cos(1)")
  expect_equal(fmt(diff_holonomic(HolonomicFunction(Dx^2 + 1, x, 0, list(0, 1)))), "HolonomicFunction((1) + (1)*Dx^2, x, 0, [1, 0])")
  expect_equal(fmt(diff_holonomic(HolonomicFunction(x*Dx^2 + Dx + x, x, 0, list(1, 0)))), "HolonomicFunction((x^2 - 1) + (x)*Dx + (x^2)*Dx^2, x, 0, [0])")
  expect_equal(fmt(shift_x(HolonomicFunction(Dx - 1, x, 0, list(1)), 2)), "HolonomicFunction((-1) + (1)*Dx, x, -2, [1])")
  expect_equal(fmt(to_meijerg(expr_to_holonomic(sin(x)))), "sqrt(pi)*x*meijerg(((), ()), ((0,), (-1/2,)), x^2/4)/2")
  expect_equal(fmt(from_hyper(hyper(list(1, 1), list(Rational(3, 2)), x^2/4))), "HolonomicFunction((4*x) + (5*x^2 - 8)*Dx + (x^3 - 4*x)*Dx^2, x, 1, [2*sqrt(3)*pi/9, -4*sqrt(3)*pi/27 + 4/3])")
  expect_equal(fmt(from_meijerg(meijerg(list(), list(), list(0), list(), x))), "HolonomicFunction((1) + (1)*Dx, x, 0, [1])")
  expect_equal(fmt(from_meijerg(meijerg(list(1), list(), list(Rational(1, 2)), list(0), x))), "HolonomicFunction((x + 1/2)*Dx + (x)*Dx^2, x, 1, [sqrt(pi)*erf(1), exp(-1)])")
  expect_equal(fmt(to_sequence(HolonomicFunction(x^2*Dx^4 + x + Dx, x))), "[(HolonomicSequence((1) + (n + 2)Sn^2 + (n^4 + 6*n^3 + 11*n^2 + 6*n)Sn^3, n), u(0) = C_0, u(1) = 0, u(2) = C_2, u(3) = C_3, 0, 1)]")
  expect_equal(fmt(to_sequence(HolonomicFunction(x^2*Dx^4 + x^3 + Dx^2, x))), "[(HolonomicSequence((1) + (n^4 + 14*n^3 + 72*n^2 + 163*n + 140)Sn^5, n), u(0) = C_0, u(1) = C_1, u(2) = 0, u(3) = 0, u(4) = 0, 0, 0)]")
  expect_equal(fmt(to_sequence(HolonomicFunction(x^3*Dx^4 + 1 + Dx^2, x))), "[(HolonomicSequence((1) + (n^4 - 2*n^3 - n^2 + 2*n)Sn + (n^2 + 3*n + 2)Sn^2, n), u(0) = C_0, u(1) = C_1, 0, 0)]")
  expect_equal(fmt(to_sequence(HolonomicFunction(3*x^3*Dx^4 + 2*x*Dx + x*Dx^3, x))), "[(HolonomicSequence((2*n) + (3*n^4 - 6*n^3 - 3*n^2 + 6*n)Sn + (n^3 + 3*n^2 + 2*n)Sn^2, n), u(0) = C_0, u(1) = C_1, u(2) = C_2, 0, 1)]")
  expect_equal(fmt(to_sequence(HolonomicFunction(x^3*Dx^5 + 1 + Dx, x))), "[(HolonomicSequence((1) + (n + 1)Sn + (n^5 - 5*n^3 + 4*n)Sn^2, n), u(0) = C_0, u(1) = C_1, u(2) = C_2, u(3) = C_3, u(4) = C_4, 0, 3)]")
  expect_equal(fmt(expr_to_holonomic(log(1+x^2))), "HolonomicFunction((x^2 - 1)*Dx + (x^3 + x)*Dx^2, x, 0, [0, 0])")
  expect_equal(fmt(to_sequence(expr_to_holonomic(log(1+x^2)))), "[(HolonomicSequence((n^2) + (n^2 + 2*n)Sn^2, n), u(0) = 0, u(1) = 0, u(2) = C_2, 0, 1)]")
  expect_equal(fmt(to_sequence(diff_holonomic(expr_to_holonomic(log(1+x^2))))), "[(HolonomicSequence((n + 2) + (n + 2)Sn^2, n), u(0) = C_0, u(1) = 0, 1, 0)]")
  expect_equal(fmt(expr_to_holonomic(erf(x) + x)), "HolonomicFunction((2*x^2 - 1)*Dx^2 + (x)*Dx^3, x, 0, [0, 1 + 2/sqrt(pi), 0])")
  expect_equal(fmt(to_sequence(expr_to_holonomic(erf(x) + x))), "[(HolonomicSequence((2*n^2 - 2*n) + (n^3 + 2*n^2 - n - 2)Sn^2, n), u(0) = 0, u(1) = 1 + 2/sqrt(pi), u(2) = 0, u(3) = C_3, 0, 2)]")
  expect_equal(fmt(expr_to_holonomic(sqrt(x))), "HolonomicFunction((-1/2) + (x)*Dx, x, 0, {1/2: [1]})")
  expect_equal(fmt(expr_to_holonomic(sqrt(x^2-x))), "HolonomicFunction((1/2 - x) + (x^2 - x)*Dx, x, 0, {1/2: [I]})")
  expect_equal(fmt(series_holonomic(expr_to_holonomic(sqrt(x^3 + x)), n = 10)), "sqrt(x) + x^(5/2)/2 - x^(9/2)/8 + x^(13/2)/16 - 5*x^(17/2)/128 + O(x^10)")
  expect_equal(fmt(series_holonomic(expr_to_holonomic(sqrt(x^2-x)))), "I*sqrt(x) - I*x^(3/2)/2 - I*x^(5/2)/8 - I*x^(7/2)/16 - 5*I*x^(9/2)/128 - 7*I*x^(11/2)/256 + O(x^6)")
  expect_equal(fmt(to_expr_holonomic(expr_to_holonomic(sqrt(x)) * expr_to_holonomic(sqrt(x^2-x)))), "I*x*sqrt(1 - x)")
  expect_equal(fmt(expr_to_holonomic(x*exp(x))), "HolonomicFunction((-x - 1) + (x)*Dx, x, 0, {1: [1]})")
  expect_equal(fmt(expr_to_holonomic(x^3)), "HolonomicFunction((-3) + (x)*Dx, x, 0, {3: [1]})")
  expect_equal(fmt(to_sequence(expr_to_holonomic(x^3))), "[(HolonomicSequence((n), n), u(0) = 1, 3, 1)]")
  expect_equal(fmt(series_holonomic(expr_to_holonomic(cos(x)^2/x^2, y0 = list("-2" = list(1, 0, -1))), n = 10)), "x^(-2) - 1 + x^2/3 - 2*x^4/45 + x^6/315 - 2*x^8/14175 + O(x^10)")
  expect_equal(fmt(to_sequence(HolonomicFunction(x*Dx^2 + Dx + x, x))), "[(HolonomicSequence((1) + (n^2 + 4*n + 4)Sn^2, n), u(0) = C_0, u(1) = 0, 0, 0)]")
  expect_equal(fmt(to_sequence(HolonomicFunction(x^2*Dx^2 + x*Dx + (x^2 - Rational(1, 4)), x))), "[(HolonomicSequence((1) + (n^2 + 3*n + 2)Sn^2, n), u(0) = C_0, u(1) = C_1, -1/2, 0), (HolonomicSequence((1) + (n^2 + 5*n + 6)Sn^2, n), u(0) = D_0, u(1) = 0, 1/2, 0)]")
})

test_that("expr_to_holonomic through Meijer G functions matches SymPy", {
  x <- Symbol("x")
  expect_equal(format(expr_to_holonomic(besselj(0, x), x)), "HolonomicFunction((x) + (1)*Dx + (x)*Dx^2, x, 0, [1, 0])")
  expect_equal(format(expr_to_holonomic(besselj(1, x), x)), "HolonomicFunction((x^2 - 1) + (x)*Dx + (x^2)*Dx^2, x, 0, [0, 1/2])")
  expect_equal(format(expr_to_holonomic(besseli(0, x), x)), "HolonomicFunction((-1) + (-x)*Dx + (2)*Dx^2 + (x)*Dx^3, x, 0, [1, 0, 1/2])")
  expect_error(expr_to_holonomic(fresnels(x), x), "expected `Rational` object, got pi^2", fixed = TRUE, class = "CoercionFailed")
  expect_error(expr_to_holonomic(fresnelc(x), x), "expected `Rational` object, got pi^2", fixed = TRUE, class = "CoercionFailed")
  expect_equal(format(expr_to_holonomic(Ei(x), x, x0 = 1)), "HolonomicFunction((1 - x)*Dx + (x)*Dx^2, x, 1, [Ei(1), E])")
  expect_equal(format(expr_to_holonomic(besselk(0, x), x, x0 = 1)), "HolonomicFunction((-x) + (1)*Dx + (x)*Dx^2, x, 1, [besselk(0, 1), -besselk(1, 1)])")
  expect_equal(format(expr_to_holonomic(bessely(0, x), x, x0 = 1)), "HolonomicFunction((3*x) + (x^2 + 2)*Dx + (4*x)*Dx^2 + (x^2)*Dx^3, x, 1, [bessely(0, 1), -bessely(1, 1), bessely(2, 1)/2 - bessely(0, 1)/2])")
  expect_equal(format(expr_to_holonomic(expint(2, x), x, x0 = 1)), "HolonomicFunction((-1) + (x)*Dx + (x)*Dx^2, x, 1, [expint(2, 1), -expint(1, 1)])")
  expect_equal(format(expr_to_holonomic(Chi(x), x, x0 = 1)), "HolonomicFunction((-2*x)*Dx + (2 - x^2)*Dx^2 + (4*x)*Dx^3 + (x^2)*Dx^4, x, 1, [Chi(1), cosh(1), -cosh(1) + sinh(1), -2*sinh(1) + 3*cosh(1)])")
  expect_equal(format(expr_to_holonomic(x*besselj(2, x), x)), "HolonomicFunction((x^2 - 3) + (-x)*Dx + (x^2)*Dx^2, x, 0, [0, 0])")
  expect_equal(format(expr_to_holonomic(besselj(0, x)^2, x)), "HolonomicFunction((4*x) + (4*x^2 + 1)*Dx + (3*x)*Dx^2 + (x^2)*Dx^3, x, 0, [1, 0, -1])")
})
